/* ---------- 启动 ---------- */
/* ---------- 全站拼音注音 ---------- */
/* pinyin-pro 动态注入：defer 队列中该库在部分环境静默失败（动态加载同一文件则正常），
   故由 app.js 自行加载并在 onload 后对已渲染区域补注音 */
(function loadPinyinLib() {
  if (typeof pinyinPro !== "undefined") return;
  var s = document.createElement("script");
  s.src = "lib/pinyin.min.js?v=" + (window.CURRENT_VERSION ? CURRENT_VERSION.version : "2");
  s.onload = function () {
    try { refreshPinyin(); } catch (e) {}
  };
  document.head.appendChild(s);
})();

/* 原理：渲染完成后用 TreeWalker 遍历文本节点，逐「连续中文段」调 pinyin-pro
   取得逐字拼音（多音字按词组定音），替换为 <ruby>字<rt>yīn</rt></ruby>。
   只碰 TextNode，任何 HTML 标签（含术语标注 span）不受影响。 */
var PINYIN_KEY = "pinyin-on";
/* 生僻字括号注音恒开（如 髳(máo)），无需开关 */
function pyMode() { return "on"; }
function pinyinEnabled() { return true; }
var _pyCache = new Map();
/* 生僻字（常用字白名单外，全站不足0.2%）输出「字(pín)」内联括号结构：
   <span class="pyz" data-ch="髳">髳<em>(máo)</em></span> —— 纯内联排版零开销，data-ch 供一键还原 */
function _segHtml(seg) {
  var key = seg + "|" + pyMode();
  if (_pyCache.has(key)) return _pyCache.get(key);
  var res = { html: null };
  if (pinyinEnabled() && typeof PY_COMMON !== "undefined") {
    var hasRare = false, k;
    for (k = 0; k < seg.length; k++) if (!PY_COMMON.has(seg[k])) { hasRare = true; break; }
    if (hasRare) {
      try {
        var arr = pinyinPro.pinyin(seg, { type: "array", toneType: "symbol" });
        var html = "";
        for (var i = 0; i < seg.length; i++) {
          var ch = seg[i];
          if (!PY_COMMON.has(ch) && arr[i] && !/^u\d/.test(arr[i])) {
            html += '<span class="pyz" data-ch="' + ch + '">' + ch + '<em>(' + arr[i] + ')</em></span>';
          } else html += ch;
        }
        res = { html: html };
      } catch (e) { res = { html: null }; }
    }
  }
  if (_pyCache.size > 4000) _pyCache.clear();
  _pyCache.set(key, res);
  return res;
}
function applyRuby(root) {
  if (!pinyinEnabled() || typeof pinyinPro === "undefined" || !root) return;
  var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: function (n) {
      if (!n.nodeValue || !/[一-鿿]/.test(n.nodeValue)) return NodeFilter.FILTER_REJECT;
      var p = n.parentElement;
      if (!p) return NodeFilter.FILTER_REJECT;
      var tag = p.tagName;
      if (tag === "RT" || tag === "SCRIPT" || tag === "STYLE") return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  var nodes = [], n;
  while ((n = walker.nextNode())) nodes.push(n);
  if (!nodes.length) return;
  root.classList.add("pinyin-on");
  root.setAttribute("data-py-mode", pyMode());
  _pyQueue.push({ nodes: nodes, i: 0 });
  if (!_pyRunning) _drainRuby();
}

/* 分片处理队列：每帧预算 ~12ms，时间轴 2 万字渐进注音而不冻结页面 */
var _pyQueue = [];
var _pyRunning = false;
function _drainRuby() {
  _pyRunning = true;
  var deadline = performance.now() + 12;
  while (_pyQueue.length && performance.now() < deadline) {
    var job = _pyQueue[0];
    var node, text, parts, frag, i, seg, html, holder;
    while (job.i < job.nodes.length && performance.now() < deadline) {
      node = job.nodes[job.i++];
      if (!node.parentNode) continue; // 期间被重新渲染移除的节点直接跳过
      text = node.nodeValue;
      parts = text.split(/([一-鿿]+)/);
      frag = document.createDocumentFragment();
      for (i = 0; i < parts.length; i++) {
        seg = parts[i];
        if (!seg) continue;
        if (/[一-鿿]/.test(seg)) {
          var segRes = _segHtml(seg);
          if (segRes && segRes.html) {
            holder = document.createElement("span");
            holder.innerHTML = segRes.html;
            frag.appendChild(holder);
          } else {
            frag.appendChild(document.createTextNode(seg));
          }
        } else {
          frag.appendChild(document.createTextNode(seg));
        }
      }
      node.parentNode.replaceChild(frag, node);
    }
    if (job.i >= job.nodes.length) _pyQueue.shift();
    else break;
  }
  if (_pyQueue.length) setTimeout(_drainRuby, 0);
  else _pyRunning = false;
}

function removeRuby(root) {
  if (!root) return;
  root.classList.remove("pinyin-on");
  /* 括号注音（.pyz span）为主；ruby 为旧版残留兼容 */
  var marks = Array.prototype.slice.call(root.querySelectorAll(".pyz, ruby"));
  if (!marks.length) return;
  _pyOffQueue.push({ marks: marks, root: root, i: 0 });
  if (!_pyOffRunning) _drainOffRuby();
}
var _pyOffQueue = [];
var _pyOffRunning = false;
function _drainOffRuby() {
  _pyOffRunning = true;
  var deadline = performance.now() + 12;
  while (_pyOffQueue.length && performance.now() < deadline) {
    var job = _pyOffQueue[0], m, text, c;
    while (job.i < job.marks.length && performance.now() < deadline) {
      m = job.marks[job.i++];
      if (!m.parentNode) continue;
      if (m.classList && m.classList.contains("pyz")) {
        m.replaceWith(document.createTextNode(m.getAttribute("data-ch") || m.textContent));
      } else {
        text = "";
        for (c = 0; c < m.childNodes.length; c++) if (m.childNodes[c].nodeType === 3) text += m.childNodes[c].nodeValue;
        m.replaceWith(document.createTextNode(text));
      }
    }
    if (job.i >= job.marks.length) { try { job.root.normalize(); } catch (e) {} _pyOffQueue.shift(); }
    else break;
  }
  if (_pyOffQueue.length) setTimeout(_drainOffRuby, 0);
  else _pyOffRunning = false;
}

function refreshPinyin() {
  var mode = pyMode();
  /* 拼音恒开，无开关按钮 */
  var roots = ["timeline", "people-grid", "modal-body", "map-info"];
  roots.forEach(function (id) {
    var el = document.getElementById(id);
    if (!el) return;
    var prev = el.getAttribute("data-py-mode") || "off";
    if (prev !== mode) { if (prev !== "off") removeRuby(el); if (mode === "on") applyRuby(el); }
    el.setAttribute("data-py-mode", mode);
  });
}



